import tkinter as tk from tkinter import ttk import threading import queue import logging
class TkinterAutoCADApp: """Main application class for Tkinter GUI with AutoCAD integration."""
def __init__(self, root): self.root = root self.root.title("AutoCAD Integration Tool") self.root.geometry("800x600")
# Threading components self.operation_queue = queue.Queue() self.worker_thread = None self.is_running = True
# AutoCAD connection (will be initialized later) self.acad_app = None
# Setup logging self.setup_logging()
# Create UI components self.create_widgets() self.setup_layout()
# Start background thread for queue processing self.start_background_worker()
def setup_logging(self): """Configure logging for the application.""" logging.basicConfig( level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s', handlers=[ logging.FileHandler('autocad_gui.log'), logging.StreamHandler() ] ) self.logger = logging.getLogger(__name__)
def create_widgets(self): """Create all UI widgets.""" # Main container self.main_frame = ttk.Frame(self.root, padding="10") self.main_frame.grid(row=0, column=0, sticky=(tk.W, tk.E, tk.N, tk.S))
# Status bar self.status_var = tk.StringVar(value="Ready") self.status_bar = ttk.Label( self.root, textvariable=self.status_var, relief=tk.SUNKEN, anchor=tk.W )
# Progress bar self.progress_var = tk.DoubleVar() self.progress_bar = ttk.Progressbar( self.root, variable=self.progress_var, maximum=100 )
def setup_layout(self): """Configure layout management.""" self.root.columnconfigure(0, weight=1) self.root.rowconfigure(0, weight=1)
# Configure main frame self.main_frame.columnconfigure(0, weight=1) self.main_frame.rowconfigure(0, weight=1)
# Position status bar and progress bar self.status_bar.grid(row=1, column=0, sticky=(tk.W, tk.E)) self.progress_bar.grid(row=2, column=0, sticky=(tk.W, tk.E))
def start_background_worker(self): """Start background thread for processing operations.""" def worker(): while self.is_running: try: operation = self.operation_queue.get(timeout=1) self.execute_operation(operation) self.operation_queue.task_done() except queue.Empty: continue except Exception as e: self.logger.error(f"Worker thread error: {e}")
self.worker_thread = threading.Thread(target=worker, daemon=True) self.worker_thread.start()
def execute_operation(self, operation): """Execute an operation in the background thread.""" try: operation() except Exception as e: self.logger.error(f"Operation failed: {e}") # Update UI with error message self.root.after(0, lambda: self.status_var.set(f"Error: {str(e)}"))
def on_closing(self): """Handle application closing.""" self.is_running = False if self.worker_thread: self.worker_thread.join(timeout=2) self.root.destroy()
if __name__ == "__main__": root = tk.Tk() app = TkinterAutoCADApp(root) root.protocol("WM_DELETE_WINDOW", app.on_closing) root.mainloop()

class ResponsiveFrame(ttk.Frame): """A frame that adapts its layout based on available space."""
def __init__(self, parent, **kwargs): super().__init__(parent, **kwargs) self.parent = parent
# Configure responsive behavior self.bind('<Configure>', self.on_resize)
# Track current layout mode self.layout_mode = 'normal' # 'normal', 'compact', 'minimal'
def on_resize(self, event): """Handle window resize events.""" width = event.width height = event.height
# Determine layout mode based on size if width < 400: new_mode = 'minimal' elif width < 600: new_mode = 'compact' else: new_mode = 'normal'
if new_mode != self.layout_mode: self.layout_mode = new_mode self.reconfigure_layout()
def reconfigure_layout(self): """Reconfigure widgets based on current layout mode.""" # Clear existing layout for child in self.winfo_children(): child.grid_forget()
if self.layout_mode == 'minimal': self.configure_minimal_layout() elif self.layout_mode == 'compact': self.configure_compact_layout() else: self.configure_normal_layout()
def configure_normal_layout(self): """Normal layout for larger screens.""" # Example widget placement ttk.Label(self, text="Parameter 1:").grid(row=0, column=0, sticky=tk.W, padx=5, pady=5) self.param1_entry.grid(row=0, column=1, sticky=(tk.W, tk.E), padx=5, pady=5)
ttk.Label(self, text="Parameter 2:").grid(row=1, column=0, sticky=tk.W, padx=5, pady=5) self.param2_entry.grid(row=1, column=1, sticky=(tk.W, tk.E), padx=5, pady=5)
# Configure column weights self.columnconfigure(1, weight=1)
def configure_compact_layout(self): """Compact layout for medium screens.""" # Stack labels and entries vertically ttk.Label(self, text="Parameter 1:").grid(row=0, column=0, sticky=tk.W, padx=5, pady=2) self.param1_entry.grid(row=1, column=0, sticky=(tk.W, tk.E), padx=5, pady=2)
ttk.Label(self, text="Parameter 2:").grid(row=2, column=0, sticky=tk.W, padx=5, pady=2) self.param2_entry.grid(row=3, column=0, sticky=(tk.W, tk.E), padx=5, pady=2)
# Single column layout self.columnconfigure(0, weight=1)
def configure_minimal_layout(self): """Minimal layout for small screens.""" # Very compact layout ttk.Label(self, text="P1:").grid(row=0, column=0, sticky=tk.W, padx=2, pady=2) self.param1_entry.grid(row=0, column=1, sticky=(tk.W, tk.E), padx=2, pady=2)
ttk.Label(self, text="P2:").grid(row=1, column=0, sticky=tk.W, padx=2, pady=2) self.param2_entry.grid(row=1, column=1, sticky=(tk.W, tk.E), padx=2, pady=2)
# Equal column weights self.columnconfigure(0, weight=1) self.columnconfigure(1, weight=1)
class InputPanel(ResponsiveFrame): """Input panel with responsive parameter entry."""
def __init__(self, parent, **kwargs): super().__init__(parent, **kwargs)
# Create input widgets self.param1_entry = ttk.Entry(self) self.param2_entry = ttk.Entry(self)
# Set initial layout self.reconfigure_layout()


import tkinter.messagebox as messagebox
import traceback
import logging

class ErrorHandler:
    """Centralized error handling for Tkinter applications."""

    def __init__(self, root, logger=None):
        self.root = root
        self.logger = logger or logging.getLogger(__name__)

    def handle_error(self, error: Exception, context: str = ""):
        """Handle an error with user-friendly display."""
        # Log the full error
        self.logger.error(f"Error in {context}: {error}")
        self.logger.error(traceback.format_exc())

        # Create user-friendly error message
        error_message = self.format_error_message(error, context)

        # Show error dialog
        def show_error():
            messagebox.showerror("Error", error_message)

        self.root.after(0, show_error)

    def format_error_message(self, error: Exception, context: str = "") -> str:
        """Format error message for user display."""
        error_type = type(error).__name__

        # Handle specific error types
        if "COM" in str(error) or "win32com" in str(error):
            return self.format_com_error(error, context)
        elif isinstance(error, ValueError):
            return self.format_value_error(error, context)
        elif isinstance(error, ConnectionError):
            return self.format_connection_error(error, context)
        else:
            return self.format_generic_error(error, context)

    def format_com_error(self, error: Exception, context: str) -> str:
        """Format COM-specific errors."""
        if "connection" in str(error).lower():
            return f"Failed to connect to AutoCAD. Please ensure AutoCAD is running and try again."
        elif "-2147352567" in str(error):
            return f"AutoCAD operation failed due to invalid parameters. Please check your input values."
        else:
            return f"AutoCAD operation failed: {str(error)}. Please check the application logs for details."

    def format_value_error(self, error: Exception, context: str) -> str:
        """Format value validation errors."""
        return f"Invalid input value: {str(error)}. Please check your entries and try again."

    def format_connection_error(self, error: Exception, context: str) -> str:
        """Format connection-related errors."""
        return f"Connection failed: {str(error)}. Please check your network connection and try again."

    def format_generic_error(self, error: Exception, context: str) -> str:
        """Format generic errors."""
        context_msg = f" in {context}" if context else ""
        return f"An unexpected error occurred{context_msg}. Please check the application logs for details."

class ValidatedEntry(ttk.Entry):
    """Entry widget with built-in validation."""

    def __init__(self, parent, validator=None, error_handler=None, **kwargs):
        super().__init__(parent, **kwargs)
        self.validator = validator
        self.error_handler = error_handler
        self.error_var = tk.StringVar()

        # Bind validation
        self.bind('<FocusOut>', self.on_validate)
        self.bind('<KeyRelease>', self.on_validate)

    def on_validate(self, event=None):
        """Validate input and display errors."""
        if self.validator:
            try:
                value = self.get()
                self.validator(value)
                self.error_var.set("")  # Clear error
                self.config(foreground='black')  # Normal text color
            except Exception as e:
                self.error_var.set(str(e))
                self.config(foreground='red')  # Error text color
                if self.error_handler:
                    self.error_handler.handle_error(e, "input validation")

    def get_validated_value(self):
        """Get value with validation."""
        if self.error_var.get():
            raise ValueError(self.error_var.get())
        return self.get()

# Example usage
def validate_coordinate(value: str) -> float:
    """Validate coordinate input."""
    try:
        coord = float(value)
        if not (-10000 <= coord <= 10000):
            raise ValueError("Coordinate must be between -10000 and 10000")
        return coord
    except ValueError:
        raise ValueError("Please enter a valid number")

# In main application
error_handler = ErrorHandler(root, logger)

# Create validated entry
x_entry = ValidatedEntry(
    input_frame,
    validator=validate_coordinate,
    error_handler=error_handler
)
x_entry.grid(row=0, column=1, sticky=(tk.W, tk.E))

# Error label
error_label = ttk.Label(input_frame, textvariable=x_entry.error_var, foreground='red')
error_label.grid(row=1, column=1, sticky=tk.W)
